// app/posts/actions.ts
'use server';

import { z } from 'zod';
import { revalidatePath } from 'next/cache';
import { redirect } from 'next/navigation';
import { verifySession } from '@/lib/dal';

const PostSchema = z.object({
  title: z.string().min(3).max(120),
  body: z.string().min(1),
});

export async function createPost(prevState: { error?: string }, formData: FormData) {
  const session = await verifySession();           // authN + authZ inside the action
  const parsed = PostSchema.safeParse(Object.fromEntries(formData));
  if (!parsed.success) return { error: 'Invalid input' };

  const post = await db.post.create({ data: { ...parsed.data, authorId: session.userId } });
  revalidatePath('/posts');
  redirect(`/posts/${post.id}`);                   // throws, so call it outside try/catch
}

// app/api/posts/[id]/route.ts
import { NextRequest } from 'next/server';

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;
  const post = await getPost(id);
  if (!post) return Response.json({ error: 'Not found' }, { status: 404 });
  return Response.json(post);
}

// app/api/webhooks/stripe/route.ts
export async function POST(request: Request) {
  const signature = request.headers.get('stripe-signature');
  const raw = await request.text(); // raw body needed for signature verification
  const event = stripe.webhooks.constructEvent(raw, signature!, process.env.STRIPE_WEBHOOK_SECRET!);
  if (event.type === 'checkout.session.completed') await fulfillOrder(event.data.object);
  return new Response(null, { status: 200 });
}

